using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using YamlDotNet.RepresentationModel;

namespace Sandbox.Tests;

/// The generated compose file (.state/compose.yml): engine/compose.yml.sbn rendered with sandbox.toml and
/// the host settings into the one file docker compose runs with.
public sealed class ComposeFileTests(SandboxFixture f) : SandboxTest(f)
{
    const string Header = """
        # Generated by .sandbox/sandbox — do not edit, change sandbox.toml instead.
        # Rendered from engine/compose.yml.sbn with sandbox.toml and this machine's settings.
        # Relative paths are relative to the .sandbox folder.
        """;

    /// Run a cheap docker command so the file is (re)generated, and return its text.
    string Generate()
    {
        var r = Run("status");
        AssertExit(r, 0);
        Assert.True(File.Exists(F.GeneratedFile), $"No generated file.\n{r}");
        return File.ReadAllText(F.GeneratedFile);
    }

    YamlMappingNode GenerateParsed() => Parse(Generate());

    static YamlMappingNode Parse(string text)
    {
        var ys = new YamlStream();
        ys.Load(new StringReader(text));
        return Assert.IsType<YamlMappingNode>(Assert.Single(ys.Documents).RootNode);
    }

    static YamlNode At(YamlNode n, params string[] path)
    {
        foreach (var k in path)
        {
            var m = Assert.IsType<YamlMappingNode>(n);
            Assert.True(m.Children.TryGetValue(new YamlScalarNode(k), out n!), $"missing key '{k}'");
        }
        return n;
    }

    static bool Has(YamlNode n, params string[] path)
    {
        foreach (var k in path)
            if (n is not YamlMappingNode m || !m.Children.TryGetValue(new YamlScalarNode(k), out n!))
                return false;
        return true;
    }

    static string Str(YamlNode n, params string[] path) =>
        Assert.IsType<YamlScalarNode>(At(n, path)).Value!;

    static string[] Seq(YamlNode n, params string[] path) =>
        Assert.IsType<YamlSequenceNode>(At(n, path)).Select(x => ((YamlScalarNode)x).Value!).ToArray();

    static string[] Keys(YamlNode n) =>
        Assert.IsType<YamlMappingNode>(n).Children.Keys.Select(k => ((YamlScalarNode)k).Value!).ToArray();

    record Bind(string Source, string Target, bool ReadOnly);

    /// The bind mounts of the desktop (the generated project mounts; home and the tmpfs placeholder skipped).
    static List<Bind> Binds(YamlNode root) =>
        Assert.IsType<YamlSequenceNode>(At(root, "services", "desktop", "volumes"))
            .OfType<YamlMappingNode>()
            .Where(m => Str(m, "type") == "bind")
            .Select(m =>
            {
                Assert.Equal(["type", "source", "target", "read_only"], Keys(m));
                var ro = Str(m, "read_only");
                Assert.Contains(ro, new[] { "true", "false" });
                return new Bind(Str(m, "source"), Str(m, "target"), ro == "true");
            })
            .ToList();

    /// A service with its YAML merge key (`<<: *hardened`) applied, as docker compose reads it.
    static YamlMappingNode Service(YamlNode root, string name)
    {
        var svc = Assert.IsType<YamlMappingNode>(At(root, "services", name));
        var r = new YamlMappingNode();
        foreach (var (k, v) in svc.Children)
            if (((YamlScalarNode)k).Value != "<<")
                r.Children[k] = v;
        if (svc.Children.TryGetValue(new YamlScalarNode("<<"), out var merge))
            foreach (var (k, v) in Assert.IsType<YamlMappingNode>(merge).Children)
                r.Children.TryAdd(k, v);
        return r;
    }

    Bind Project(bool ro) => new(F.ProjectDir, F.WorkDir, ro);
    Bind SandboxDir => new(F.Dir, F.WorkDir + "/.sandbox", true);
    Bind GitConfig => new(Path.Combine(F.ProjectDir, ".git", "config"), F.WorkDir + "/.git/config", true);
    Bind GitHooks => new(Path.Combine(F.ProjectDir, ".git", "hooks"), F.WorkDir + "/.git/hooks", true);

    [DllImport("libc")]
    static extern uint getuid();

    [DllImport("libc")]
    static extern uint getgid();

    static (uint, uint) ExpectedIds()
    {
        if (OperatingSystem.IsWindows())
            return (1000, 1000);
        var (u, g) = (getuid(), getgid());
        return u == 0 ? (1000, 1000) : (u, g);
    }

    static string Q(string s) => "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

    /// The default sandbox.toml with extra lines appended to one of its sections.
    void Append(string section, string lines)
    {
        var conf = File.ReadAllText(F.ConfFile);
        var at = conf.IndexOf($"[{section}]\n", StringComparison.Ordinal);
        if (at < 0)
            conf += $"\n[{section}]\n{lines}";
        else
        {
            at += section.Length + 3;
            conf = conf[..at] + lines + conf[at..];
        }
        WriteConf(conf);
    }

    string Env(string key) => Str(Service(GenerateParsed(), "desktop"), "environment", key);

    // --- the default file -------------------------------------------------------

    [Fact]
    public void Default_file_matches_exactly()
    {
        var (uid, gid) = ExpectedIds();
        string Vol(Bind b) =>
            $"      - {{type: bind, source: {Q(b.Source)}, target: {Q(b.Target)}, read_only: {(b.ReadOnly ? "true" : "false")}}}";
        var expected = string.Join(
            "\n",
            Header.ReplaceLineEndings("\n"),
            "networks:",
            "  sandbox:            # desktop <-> proxy/gateway; NO internet route",
            "    internal: true",
            "  egress: {}          # proxy -> internet",
            "  ui: {}              # gateway -> published localhost port",
            "",
            "x-hardened: &hardened",
            "  read_only: true",
            "  cap_drop: [ALL]",
            "  security_opt: [\"no-new-privileges:true\"]",
            "  restart: unless-stopped",
            "  volumes:",
            "    - .:/sandbox:ro   # tinyproxy.conf + allowlist.txt",
            "",
            "services:",
            "  proxy:",
            "    <<: *hardened",
            "    build: ./engine/proxy",
            "    command: [\"tinyproxy\", \"-d\", \"-c\", \"/sandbox/engine/proxy/tinyproxy.conf\"]",
            "    networks: [sandbox, egress]",
            "    extra_hosts:",
            "      - \"host.docker.internal:host-gateway\"   # only reachable if allowlisted",
            "    healthcheck:",
            "      test: [\"CMD\", \"nc\", \"-z\", \"127.0.0.1\", \"3128\"]",
            "      interval: 10s",
            "      timeout: 3s",
            "      retries: 3",
            "",
            "  gateway:",
            "    <<: *hardened",
            "    build: ./engine/proxy",
            "    command: [\"socat\", \"TCP-LISTEN:3001,fork,reuseaddr\", \"TCP:desktop:3001\"]",
            "    networks: [sandbox, ui]",
            "    ports:",
            "      - \"127.0.0.1::3001\"",
            "    depends_on: [proxy]",
            "",
            "  desktop:",
            "    build:",
            "      context: ./engine/desktop",
            "      args:",
            "        INSTALL_CLAUDE: \"true\"",
            "        INSTALL_CLAUDE_CODE: \"false\"",
            "        INSTALL_DOTNET: \"10.0\"",
            "        INSTALL_NODE: \"false\"",
            "    hostname: sandbox",
            "    shm_size: 1gb",
            "    labels:",
            $"      sandbox.id: \"{SandboxFixture.Id}\"",
            "    environment:",
            "      TITLE: \"AI Sandbox\"",
            "      SANDBOX_SUDO: \"true\"",
            "      HTTP_PROXY: http://proxy:3128",
            "      HTTPS_PROXY: http://proxy:3128",
            "      http_proxy: http://proxy:3128",
            "      https_proxy: http://proxy:3128",
            "      NO_PROXY: localhost,127.0.0.1,::1",
            "      no_proxy: localhost,127.0.0.1,::1",
            $"      PUID: \"{uid}\"",
            $"      PGID: \"{gid}\"",
            "      TZ: \"Europe/Vienna\"",
            $"      SANDBOX_WORKDIR: \"{F.WorkDir}\"",
            "    volumes:",
            "      - home:/config            # persistent home: logins, IDE settings, Toolbox IDEs",
            Vol(Project(false)),
            Vol(SandboxDir),
            Vol(GitConfig),
            Vol(GitHooks),
            "    networks: [sandbox]",
            "    mem_limit: \"8g\"",
            "    pids_limit: 4096",
            "    depends_on: [proxy]",
            "    restart: unless-stopped",
            "    healthcheck:",
            "      # Ready = web UI answers AND the KDE shell is running (avoids the",
            "      # \"first page load fails\" race when the browser opens too early).",
            "      test: [\"CMD-SHELL\", \"curl -skf -o /dev/null https://localhost:3001/ && pgrep -f plasmashell >/dev/null\"]",
            "      interval: 5s",
            "      timeout: 5s",
            "      retries: 3",
            "      start_period: 180s",
            "",
            "volumes:",
            "  home:",
            ""
        );
        var text = Generate();
        Assert.Equal(expected, text);
        Assert.DoesNotContain("\r", text);
        Assert.DoesNotContain("\n...", text);
        Assert.False(File.ReadAllBytes(F.GeneratedFile).AsSpan().StartsWith(Encoding.UTF8.Preamble), "BOM");
    }

    [Fact]
    public void Default_file_parses()
    {
        var root = GenerateParsed();
        Assert.Equal(["networks", "x-hardened", "services", "volumes"], Keys(root));
        Assert.Equal(["proxy", "gateway", "desktop"], Keys(At(root, "services")));
        Assert.Equal(["127.0.0.1::3001"], Seq(root, "services", "gateway", "ports"));
        Assert.Equal(SandboxFixture.Id, Str(root, "services", "desktop", "labels", "sandbox.id"));
        Assert.Equal(F.WorkDir, Env("SANDBOX_WORKDIR"));
        Assert.Equal("Europe/Vienna", Env("TZ"));
        Assert.Equal([Project(false), SandboxDir, GitConfig, GitHooks], Binds(root));
    }

    /// The x-hardened settings apply to proxy and gateway (through the merge key), not to the desktop.
    [Fact]
    public void Proxy_and_gateway_are_hardened()
    {
        var root = GenerateParsed();
        foreach (var s in new[] { "proxy", "gateway" })
        {
            var svc = Service(root, s);
            Assert.Equal("true", Str(svc, "read_only"));
            Assert.Equal(["ALL"], Seq(svc, "cap_drop"));
            Assert.Equal(["no-new-privileges:true"], Seq(svc, "security_opt"));
            Assert.Equal([".:/sandbox:ro"], Seq(svc, "volumes"));
        }
        Assert.False(Has(Service(root, "desktop"), "read_only"));
        Assert.Contains("TCP-LISTEN:3001,fork,reuseaddr", Seq(root, "services", "gateway", "command"));
    }

    [Fact]
    public void Shipped_sandbox_toml_renders_all_tools()
    {
        File.Copy(Path.Combine(F.RepoSandboxDir, "sandbox.toml"), F.ConfFile, overwrite: true);
        var args = At(GenerateParsed(), "services", "desktop", "build", "args");
        Assert.Equal(
            ["INSTALL_CLAUDE", "INSTALL_CLAUDE_CODE", "INSTALL_DOTNET", "INSTALL_NODE", "INSTALL_BUN", "INSTALL_VSCODE", "INSTALL_JETBRAINS", "INSTALL_APT"],
            Keys(args)
        );
        Assert.Equal("", Str(args, "INSTALL_APT"));
    }

    // --- [project] -----------------------------------------------------

    [Fact]
    public void Fixed_ui_port()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("# ui_port = 3001", "ui_port = 3002"));
        Assert.Equal(["127.0.0.1:3002:3001"], Seq(GenerateParsed(), "services", "gateway", "ports"));
    }

    [Fact]
    public void Read_only_workspace_has_no_git_mounts()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("workspace = \"rw\"", "workspace = \"ro\""));
        Assert.Equal([Project(true), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Protect_git_off()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("protect_git = true", "protect_git = false"));
        Assert.Equal([Project(false), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Only_existing_git_paths_are_protected()
    {
        Directory.Delete(Path.Combine(F.ProjectDir, ".git", "hooks"));
        Assert.Equal([Project(false), SandboxDir, GitConfig], Binds(GenerateParsed()));

        Directory.Delete(Path.Combine(F.ProjectDir, ".git"), recursive: true);
        Assert.Equal([Project(false), SandboxDir], Binds(GenerateParsed()));
    }

    [Fact]
    public void Project_name_does_not_change_the_mount_path()
    {
        WriteConf(File.ReadAllText(F.ConfFile).Replace("# name = \"myproject\"", "name = \"other\""));
        Assert.Equal(F.WorkDir, Env("SANDBOX_WORKDIR"));
    }

    [Fact]
    public void A_new_id_is_derived_from_the_project_path_and_kept()
    {
        File.Delete(F.IdFile);
        var id = Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(F.ProjectDir)))[..8];
        var root = GenerateParsed();
        Assert.Equal(id + "\n", File.ReadAllText(F.IdFile));
        Assert.Equal(id, Str(root, "services", "desktop", "labels", "sandbox.id"));
        Assert.Equal(
            $"/work/{SandboxFixture.ProjectName}-{id}",
            Str(root, "services", "desktop", "environment", "SANDBOX_WORKDIR")
        );

        // a stored id is used as-is, even if it doesn't match the path (the project was moved)
        File.WriteAllText(F.IdFile, "cafebabe\n");
        Assert.Equal("cafebabe", Str(GenerateParsed(), "services", "desktop", "labels", "sandbox.id"));
    }

    [Fact]
    public void File_is_regenerated_on_every_docker_command()
    {
        File.WriteAllText(F.GeneratedFile, "stale");
        Assert.StartsWith(Header.ReplaceLineEndings("\n") + "\n", Generate());
        foreach (var cmd in new[] { "stop", "reload", "logs" })
        {
            File.WriteAllText(F.GeneratedFile, "stale");
            AssertExit(Run(cmd), 0);
            Assert.StartsWith(Header.ReplaceLineEndings("\n") + "\n", File.ReadAllText(F.GeneratedFile));
        }
    }

    [Fact]
    public void The_old_override_file_is_removed()
    {
        var old = Path.Combine(F.StateDir, "compose.generated.yml");
        File.WriteAllText(old, "services: {}\n");
        Generate();
        Assert.False(File.Exists(old));
    }

    // --- [tools] -------------------------------------------------------------------

    [Fact]
    public void Tool_values_become_build_args()
    {
        WriteConf(
            "[tools]\nclaude = true\nnode = 24\ndotnet = [\"10.0\", \"8.0\"]\njetbrains = \"toolbox rider\"\napt = []\nbun = false\n"
        );
        var args = At(GenerateParsed(), "services", "desktop", "build", "args");
        Assert.Equal(["INSTALL_CLAUDE", "INSTALL_NODE", "INSTALL_DOTNET", "INSTALL_JETBRAINS", "INSTALL_APT", "INSTALL_BUN"], Keys(args));
        Assert.Equal("true", Str(args, "INSTALL_CLAUDE"));
        Assert.Equal("24", Str(args, "INSTALL_NODE"));
        Assert.Equal("10.0 8.0", Str(args, "INSTALL_DOTNET"));
        Assert.Equal("toolbox rider", Str(args, "INSTALL_JETBRAINS"));
        Assert.Equal("", Str(args, "INSTALL_APT"));
        Assert.Equal("false", Str(args, "INSTALL_BUN"));
        Assert.Equal("./engine/desktop", Str(GenerateParsed(), "services", "desktop", "build", "context"));
    }

    [Fact]
    public void An_empty_sandbox_toml_uses_the_defaults()
    {
        WriteConf("");
        var root = GenerateParsed();
        var desktop = Service(root, "desktop");
        Assert.False(Has(desktop, "build", "args", "INSTALL_CLAUDE"));
        Assert.Equal("AI Sandbox", Str(desktop, "environment", "TITLE"));
        Assert.Equal("true", Str(desktop, "environment", "SANDBOX_SUDO"));
        Assert.Equal("8g", Str(desktop, "mem_limit"));
        Assert.False(Has(desktop, "cpus"));
        Assert.False(Has(desktop, "devices"));
        Assert.False(Has(desktop, "environment", "CUSTOM_USER"));
        Assert.Equal([Project(false), SandboxDir, GitConfig, GitHooks], Binds(root));
    }

    // --- [desktop] and [env] ---------------------------------------------------------

    [Fact]
    public void Desktop_settings()
    {
        Append(
            "desktop",
            "sudo = false\nmemory = \"4g\"\ncpus = 2.5\ntimezone = \"Asia/Tokyo\"\ndevices = [\"/dev/dri:/dev/dri\"]\n"
                + "security_opt = [\"seccomp=unconfined\"]\nauth = { user = \"me\", password = \"secret\" }\n"
        );
        var d = Service(GenerateParsed(), "desktop");
        Assert.Equal("false", Str(d, "environment", "SANDBOX_SUDO"));
        Assert.Equal("4g", Str(d, "mem_limit"));
        Assert.Equal("2.5", Str(d, "cpus"));
        Assert.Equal("Asia/Tokyo", Str(d, "environment", "TZ"));
        Assert.Equal(["/dev/dri:/dev/dri"], Seq(d, "devices"));
        Assert.Equal(["seccomp=unconfined"], Seq(d, "security_opt"));
        Assert.Equal("me", Str(d, "environment", "CUSTOM_USER"));
        Assert.Equal("secret", Str(d, "environment", "PASSWORD"));
    }

    [Fact]
    public void Whole_cpus_are_written_as_numbers()
    {
        Append("desktop", "cpus = 4\n");
        Assert.Equal("4", Str(Service(GenerateParsed(), "desktop"), "cpus"));
        Assert.Contains("\n    cpus: 4\n", File.ReadAllText(F.GeneratedFile));
    }

    [Fact]
    public void Env_vars_are_added_after_the_sandbox_ones()
    {
        WriteConf(File.ReadAllText(F.ConfFile) + "\n[env]\nMY_VAR = \"a=b\"\nCOUNT = 3\nFLAG = true\n");
        var env = Keys(At(Service(GenerateParsed(), "desktop"), "environment"));
        Assert.Equal(["MY_VAR", "COUNT", "FLAG"], env[^3..]);
        Assert.Equal("SANDBOX_WORKDIR", env[^4]);
        Assert.Equal("a=b", Env("MY_VAR"));
        Assert.Equal("3", Env("COUNT"));
        Assert.Equal("true", Env("FLAG"));
    }

    /// Values go through `q`: quotes, backslashes, `: #`, newlines and Windows paths can't break or inject YAML.
    [Fact]
    public void Values_are_escaped()
    {
        const string title = "My \"box\": #1 \\ yes\n  injected: true";
        WriteConf(
            File.ReadAllText(F.ConfFile).Replace("title = \"AI Sandbox\"", "title = '''" + title + "'''")
                + "\n[env]\nWIN = 'C:\\Users\\me'\nTAB = \"a\\tb\\u0001\"\n"
        );
        var d = Service(GenerateParsed(), "desktop");
        Assert.Equal(title, Str(d, "environment", "TITLE"));
        Assert.Equal("C:\\Users\\me", Str(d, "environment", "WIN"));
        Assert.Equal("a\tb\u0001", Str(d, "environment", "TAB"));
        Assert.False(Has(d, "injected"));
        Assert.False(Has(d, "environment", "injected"));
    }

    // --- [[share]] -----------------------------------------------------------------

    [Fact]
    public void Shares_are_mounted_after_the_project()
    {
        var docs = Path.Combine(F.Root, "docs");
        var data = Path.Combine(F.Root, "my data");
        Directory.CreateDirectory(docs);
        Directory.CreateDirectory(data);
        WriteConf(
            File.ReadAllText(F.ConfFile)
                + "\n[[share]]\nhost = \"../docs\"\n\n[[share]]\nhost = \"../my data\"\npath = \"/data\"\nreadonly = false\n"
        );
        Assert.Equal(
            [Project(false), SandboxDir, GitConfig, GitHooks, new(docs, "/shares/docs", true), new(data, "/data", false)],
            Binds(GenerateParsed())
        );
    }

    [Fact]
    public void Shares_are_listed_by_info()
    {
        Directory.CreateDirectory(Path.Combine(F.Root, "docs"));
        WriteConf(File.ReadAllText(F.ConfFile) + "\n[[share]]\nhost = \"../docs\"\n");
        var r = Run("info");
        AssertExit(r, 0);
        AssertOutput(r, "/shares/docs");
        AssertOutput(r, "read-only");
    }

    // --- the template ----------------------------------------------------------------

    [Fact]
    public void Template_errors_are_reported()
    {
        var path = Path.Combine(F.Dir, "engine", "compose.yml.sbn");
        var original = File.ReadAllText(path);
        try
        {
            File.WriteAllText(path, "services: {{ nope.value }}\n");
            var r = Run("status");
            AssertExit(r, 1);
            AssertOutput(r, "engine/compose.yml.sbn:");

            File.WriteAllText(path, "services: {{ for x in }}\n");
            r = Run("status");
            AssertExit(r, 1);
            AssertOutput(r, "engine/compose.yml.sbn is not a valid template");
        }
        finally
        {
            File.WriteAllText(path, original);
        }
    }
}
